// ai-agents/orchestrator/src/workflows/routine-run.ts: sketch, not final code. Workflow code: deterministic, no Node APIs.
import { proxyActivities, defineSignal, setHandler, sleep, executeChild, workflowInfo } from "@temporalio/workflow";
import type * as activities from "../activities/index.js";
import type { PlanDecision, RoutineRequest, RunOutcome, Trigger } from "@rhinohealth/ai-agents-shared";
import { TaskSpec } from "../routines/task-spec.js";  // pure code, safe to bundle into a workflow
import { shipPr } from "./ship-pr.js";  // the PR half of ticketToPr, shared with Nova
const { loadCharter, preRunGate, saveShadowResult } = proxyActivities<typeof activities>({ startToCloseTimeout: "1 minute" });
const { acquireSandbox } = proxyActivities<typeof activities>({ startToCloseTimeout: "10 minutes" });
const { releaseSandbox } = proxyActivities<typeof activities>({ startToCloseTimeout: "5 minutes" });
const { workInSandbox } = proxyActivities<typeof activities>({  // ticketToPr's activity (G3)
  startToCloseTimeout: "7 days", heartbeatTimeout: "5 minutes" });  // no work-time limit: these only catch a dead worker
export const addTrigger = defineSignal<[Trigger]>("addTrigger");  // target of signal-with-start (G5-09)
export const decidePlan = defineSignal<[PlanDecision]>("decidePlan");  // same Slack buttons as Nova; bug fixers (G5-27)

export async function routineRun(req: RoutineRequest): Promise<string> {
  const triggers: Trigger[] = [];  // every event with the same root cause lands here
  let planDecision: PlanDecision | undefined;  // read by the bug fixers' plan step (G5-27)
  setHandler(addTrigger, (t) => void triggers.push(t));
  setHandler(decidePlan, (d) => { planDecision = d; });
  const charter = await loadCharter(req.routine, req.charterSha);
  if (req.trigger) triggers.push(req.trigger);  // schedules and Jira start without a signal
  if (charter.gather_minutes) await sleep(charter.gather_minutes * 60_000);  // 7 for red main, 0 for bugs (G5-17)
  const gate = await preRunGate(charter, triggers);
  if (gate.verdict !== "go") return park(charter, gate);  // kill switch, paused, incident mode, an open PR: no VM
  const task = TaskSpec.fromCharter(charter, triggers);  // goal, done, skills, paths, model and effort
  const vm = await acquireSandbox({ runId: workflowInfo().runId, agent: req.routine, ...charter.vm });
  let result: RunOutcome;
  try {  // a bigger bug fix returns needs_plan_approval, waits on decidePlan, then resumes in the same VM (G5-27)
    result = await workInSandbox(vm, task);
  } finally {
    await releaseSandbox(vm);
  }
  if (charter.effectiveStage === "shadow") return saveShadowResult(charter, result);  // opens nothing: diff + proof to S3
  return executeChild(shipPr, { args: [{ charter, result }] });
}

// ai-agents/orchestrator/src/triggers/github-events.ts: sketch: POST /v1/events → one routineRun per root cause
import { createHash } from "node:crypto";
import { WorkflowExecutionAlreadyStartedError, WorkflowIdReusePolicy, type Client } from "@temporalio/client";
import { addTrigger, routineRun } from "../workflows/routine-run.js";
const ROUTINES: Record<string, string> = {  // "<workflow name>|<main or renovate>" → routine
  "[FRONTEND] - CI|main": "fe-ci-fixer", "[CLOUD] - CI|main": "be-ci-fixer", "[CLIENT] - CI|main": "be-ci-fixer",
  "[FRONTEND] - CI|renovate": "fe-upgrade-fixer", "[CLOUD] - CI|renovate": "be-upgrade-fixer",
  "[CLIENT] - CI|renovate": "be-upgrade-fixer", "[SDK] - CI|renovate": "be-upgrade-fixer" };

export async function onFailedRun(temporal: Client, ev: WorkflowRunEvent): Promise<string | undefined> {
  const run = await broker.github.getRun(ev.repo, ev.run_id);  // re-read from GitHub; never trust the body
  const kind = run.head_branch === "main" ? "main" : run.head_branch.startsWith("renovate/") ? "renovate" : undefined;
  const routine = kind && ROUTINES[`${run.name}|${kind}`];  // run.name: the workflow's name in GitHub's JSON
  if (!routine || run.conclusion !== "failure") return undefined;
  const workflowId = kind === "renovate"
    ? `upgrade:${ev.repo}:pr-${await broker.github.prForBranch(ev.repo, run.head_branch)}`
    : `cifix:${ev.repo}:${fingerprint(await broker.github.lastGreenSha(ev.repo, run.workflow_id, { branch: "main" }),
                                      await broker.github.failedJobs(ev.repo, run.id))}`;  // name + first error line of each log

  await temporal.workflow.signalWithStart(routineRun, { workflowId, taskQueue: queueFor(routine), args: [{ routine }],
    signal: addTrigger, signalArgs: [Trigger.fromRun(run)],  // joins an open run
    typedSearchAttributes: agentAttribute(routine),  // Agent=cifix|upgrade, as startRun sets it (G3-25)
    workflowIdReusePolicy: WorkflowIdReusePolicy.REJECT_DUPLICATE,  // one run per root cause
  }).catch(async (err: unknown) => {
    if (!(err instanceof WorkflowExecutionAlreadyStartedError)) throw err;
    await alerts.post(`${workflowId} came back after its run closed; a person should look (ping-pong?)`);
  });
  return workflowId;
}

export function fingerprint(baseSha: string, jobs: FailedJob[]): string {
  const parts = jobs.map((j) => `${j.name}|${normalize(j.firstError)}`).sort();
  return createHash("sha256").update([baseSha, ...parts].join("\n")).digest("hex").slice(0, 12);
}
export function normalize(line: string): string {  // drop what changes between runs of the same failure
  return line.toLowerCase().replace(/\b[0-9a-f]{7,40}\b|0x[0-9a-f]+/g, "<hex>").replace(/\d+(\.\d+)?/g, "<n>").slice(0, 200);
}

# No checkout and no ${{ }} inside the script: event fields are read in JS, so nothing can be injected.
- uses: actions/github-script@v9   # pin by SHA with the rest of the Actions (G5-04)
  env:
    TRIGGER_URL: ${{ vars.AI_AGENTS_TRIGGER_URL }}
  with:
    script: |
      const run = context.payload.workflow_run
      const token = await core.getIDToken("rhino-ai-agents")
      const res = await fetch(`${process.env.TRIGGER_URL}/v1/events`, {
        method: "POST",
        headers: {authorization: `Bearer ${token}`, "content-type": "application/json"},
        body: JSON.stringify({kind: "github.workflow_run", repo: context.repo.repo, run_id: run.id})
      })
      if (!res.ok) core.setFailed(`trigger service answered ${res.status}`)

// ai-agents/orchestrator/src/triggers/schedules.ts: sketch; G5's part of the file G3-28 creates. Safe to run twice.
import { ScheduleAlreadyRunning, ScheduleOverlapPolicy, type Client, type Workflow } from "@temporalio/client";
import { noiseSweep, routineRun, shadowReport, teamDigest, trustLadder } from "../workflows/index.js";

const BUG_JQL = (label: string) =>
  'project = RH AND issuetype = Bug AND statusCategory = "To Do" AND assignee is EMPTY ' +
  `AND labels = ${label} AND labels not in (no-routine)`; // + Security's customer-data label
// Bug polls use G3-28's registry, like Nova's: one Jira mechanism, one run per ticket (bugfix:RH-1240).
for (const team of ["fe", "be"] as const) {
  QUERIES.set(`bugfix-${team}`, { name: `bugfix-${team}`, agent: "bugfix", every: "5 minutes",
    jql: BUG_JQL(team.toUpperCase()), // the label agreed in G5-07 (proposal: FE / BE)
    toStart: (issue) => [routineRun, { routine: `${team}-bug-fixer`, trigger: { kind: "jira", key: issue.key } }] });
}

const CRON: Record<string, [cron: string, workflow: Workflow, args: unknown[]]> = { // odd minutes; 0-4 = Sun–Thu
  "fe-dead-code": ["17 4 * * 0-4", routineRun, [{ routine: "fe-dead-code" }]],
  "kb-ingest": ["41 6 * * 1", routineRun, [{ routine: "kb-ingest" }]], // G6-20
  "noise-close": ["23 3 * * *", noiseSweep, ["fcp"]],   // G5-02
  "team-digest": ["37 6 * * 0-4", teamDigest, []],      // G5-03
  "trust-ladder": ["51 5 * * *", trustLadder, []],      // G5-15
  "shadow-report": ["13 7 * * 0", shadowReport, []],    // G5-16
};

/** At worker start, next to G3-28's ensureSchedules (the Jira polls). */
export async function ensureCronSchedules(client: Client): Promise<void> {
  for (const [name, [cron, workflowType, args]] of Object.entries(CRON)) {
    const scheduleId = `sched:${name}`;
    const schedule = {
      spec: { cronExpressions: [cron], timezone: "Asia/Jerusalem" },
      action: { type: "startWorkflow" as const, workflowType, args, workflowId: scheduleId, taskQueue: queueFor(name) },
      policies: { overlap: ScheduleOverlapPolicy.SKIP }, // a slow run never stacks a second one
    };
    await client.schedule.create({ scheduleId, ...schedule }).catch(async (err: unknown) => {
      if (!(err instanceof ScheduleAlreadyRunning)) throw err;
      await client.schedule.getHandle(scheduleId).update((previous) => ({ ...previous, ...schedule }));
    });
  }
}

