import { proxyActivities, defineSignal, setHandler, sleep, executeChild, workflowInfo } from "@temporalio/workflow";
import type { Activities } from "./activities.js";
import type { Charter, Gate, RoutineRequest, RunOutcome, Task, Trigger } from "./types.js";

const { loadCharter, preRunGate, saveShadowResult } = proxyActivities<Activities>({ startToCloseTimeout: "1 minute" });
const { acquireSandbox } = proxyActivities<Activities>({ startToCloseTimeout: "10 minutes" });
const { releaseSandbox } = proxyActivities<Activities>({ startToCloseTimeout: "5 minutes" });
const { workInSandbox } = proxyActivities<Activities>({ startToCloseTimeout: "7 days", heartbeatTimeout: "5 minutes" });
export const addTrigger = defineSignal<[Trigger]>("addTrigger");

const fromCharter = (c: Charter, triggers: Trigger[]): Task => ({ goal: `${c.name}: ${triggers.length} trigger(s)`, triggers });
const park = (c: Charter, gate: Gate): string => `${c.name} parked: ${gate.reason}`;  // the real one waits on a timer

export async function shipPr(c: Charter, r: RunOutcome): Promise<string> { return `PR for ${c.name}: ${r.diff}`; }

export async function routineRun(req: RoutineRequest): Promise<string> {
  const triggers: Trigger[] = [];
  setHandler(addTrigger, (t) => void triggers.push(t));
  const charter = await loadCharter(req.routine, req.charterSha);
  if (req.trigger) triggers.push(req.trigger);
  if (charter.gather_minutes) await sleep(charter.gather_minutes * 60_000);
  const gate = await preRunGate(charter, triggers);
  if (gate.verdict !== "go") return park(charter, gate);
  const vm = await acquireSandbox({ runId: workflowInfo().runId, agent: req.routine, size: charter.vm.size });
  let result: RunOutcome;
  try {
    result = await workInSandbox(vm, fromCharter(charter, triggers));
  } finally {
    await releaseSandbox(vm);
  }
  if (charter.effectiveStage === "shadow") return saveShadowResult(charter, result);
  return executeChild(shipPr, { args: [charter, result] });
}

