import { after, before, test } from "node:test";
import assert from "node:assert/strict";
import { fileURLToPath } from "node:url";
import { TestWorkflowEnvironment } from "@temporalio/testing";
import { DefaultLogger, Runtime, Worker } from "@temporalio/worker";
import { addTrigger, routineRun } from "../src/workflows.js";
import type { Charter, Gate, Task } from "../src/types.js";

Runtime.install({ logger: new DefaultLogger("WARN") });  // quiet: only warnings and errors
let env: TestWorkflowEnvironment;
before(async () => { env = await TestWorkflowEnvironment.createTimeSkipping(); });
after(async () => { await env?.teardown(); });

function mocks(charter: Charter, gate: Gate = { verdict: "go", reason: "" }) {
  const calls: string[] = [];
  let task: Task | undefined;
  const activities = {
    loadCharter: async () => charter,
    preRunGate: async () => gate,
    acquireSandbox: async () => { calls.push("acquire"); return "vm-1"; },
    workInSandbox: async (_vm: string, t: Task) => { calls.push("work"); task = t; return { diff: "+1 -1" }; },
    releaseSandbox: async () => { calls.push("release"); },
    saveShadowResult: async () => { calls.push("shadow"); return "saved to S3"; },
  };
  return { activities, calls, task: () => task };
}

async function run(m: ReturnType<typeof mocks>, start: (taskQueue: string) => Promise<string>): Promise<string> {
  const taskQueue = `q-${Math.random()}`;
  const worker = await Worker.create({ connection: env.nativeConnection, taskQueue, activities: m.activities,
    workflowsPath: fileURLToPath(new URL("../src/workflows.ts", import.meta.url)) });
  return worker.runUntil(start(taskQueue));
}

const shadow: Charter = { name: "fe-ci-fixer", effectiveStage: "shadow", gather_minutes: 7, vm: { size: "lite" } };

test("a shadow run saves its result and opens nothing", async () => {
  const m = mocks(shadow);
  const out = await run(m, (taskQueue) => env.client.workflow.execute(routineRun,
    { taskQueue, workflowId: "cifix:fcp:abc", args: [{ routine: "fe-ci-fixer", charterSha: "sha1" }] }));
  assert.equal(out, "saved to S3");
  assert.deepEqual(m.calls, ["acquire", "work", "release", "shadow"]);
});

test("a gate that says wait never claims a VM", async () => {
  const m = mocks(shadow, { verdict: "wait", reason: "#2501 is still open" });
  const out = await run(m, (taskQueue) => env.client.workflow.execute(routineRun,
    { taskQueue, workflowId: "cifix:fcp:def", args: [{ routine: "fe-ci-fixer", charterSha: "sha1" }] }));
  assert.equal(out, "fe-ci-fixer parked: #2501 is still open");
  assert.deepEqual(m.calls, []);
});

test("events with the same root cause join one run", async () => {
  const m = mocks(shadow);
  await run(m, async (taskQueue) => {
    const opts = { taskQueue, workflowId: "cifix:fcp:ghi", args: [{ routine: "fe-ci-fixer", charterSha: "sha1" }],
      signal: addTrigger, signalArgs: [{ kind: "github.workflow_run", ref: "run-1" }] } as const;
    const handle = await env.client.workflow.signalWithStart(routineRun, opts);
    await env.client.workflow.signalWithStart(routineRun, { ...opts, signalArgs: [{ kind: "github.workflow_run", ref: "run-2" }] });
    return handle.result();
  });
  assert.equal(m.task()?.triggers.length, 2);
});
